CREATE TABLE IF NOT EXISTS schema_migrations (version INT PRIMARY KEY, applied_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (id VARCHAR(36) PRIMARY KEY, slug VARCHAR(191) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, description TEXT NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS projects (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL, slug VARCHAR(191) NOT NULL, name VARCHAR(255) NOT NULL, description TEXT NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_projects_workspace_slug(workspace_id,slug), CONSTRAINT fk_projects_workspace FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skills (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NULL, project_id VARCHAR(36) NULL, slug VARCHAR(191) NOT NULL, name VARCHAR(255) NOT NULL, description TEXT NOT NULL, purpose TEXT NOT NULL, when_to_use TEXT NOT NULL, when_not_to_use TEXT NOT NULL, instructions LONGTEXT NOT NULL, success_criteria LONGTEXT NOT NULL, scope VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, priority INT NOT NULL DEFAULT 0, current_version INT NOT NULL DEFAULT 1, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_skills_slug_scope(slug,workspace_id,project_id), KEY idx_skills_lookup(status,scope,workspace_id,project_id,priority), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(project_id) REFERENCES projects(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_domains (skill_id VARCHAR(36) NOT NULL, value VARCHAR(191) NOT NULL, PRIMARY KEY(skill_id,value), FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_intents LIKE skill_domains;
ALTER TABLE skill_intents ADD CONSTRAINT fk_skill_intents_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_object_types LIKE skill_domains;
ALTER TABLE skill_object_types ADD CONSTRAINT fk_skill_object_types_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_tags LIKE skill_domains;
ALTER TABLE skill_tags ADD CONSTRAINT fk_skill_tags_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_keywords LIKE skill_domains;
ALTER TABLE skill_keywords ADD CONSTRAINT fk_skill_keywords_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_capabilities LIKE skill_domains;
ALTER TABLE skill_capabilities ADD CONSTRAINT fk_skill_capabilities_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_compatibility LIKE skill_domains;
ALTER TABLE skill_compatibility ADD CONSTRAINT fk_skill_compatibility_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_steps (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL, position INT NOT NULL, title VARCHAR(255) NOT NULL, instruction TEXT NOT NULL, condition_text TEXT NULL, is_required BOOLEAN NOT NULL, expected_result TEXT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_skill_steps_position(skill_id,position), FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_tools (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL, tool_name VARCHAR(191) NOT NULL, tool_namespace VARCHAR(191) NULL, requirement VARCHAR(32) NOT NULL, purpose TEXT NOT NULL, usage_hint TEXT NULL, FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_context_requirements (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL, type VARCHAR(64) NOT NULL, query_text TEXT NOT NULL, description TEXT NOT NULL, required BOOLEAN NOT NULL, priority INT NOT NULL DEFAULT 0, max_tokens INT NULL, FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_dependencies (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL, depends_on_skill_id VARCHAR(36) NOT NULL, type VARCHAR(32) NOT NULL, position INT NOT NULL DEFAULT 0, UNIQUE KEY uq_skill_dependency(skill_id,depends_on_skill_id,type), FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE, FOREIGN KEY(depends_on_skill_id) REFERENCES skills(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_examples (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL, title VARCHAR(255) NOT NULL, input_example TEXT NOT NULL, expected_behavior TEXT NOT NULL, bad_behavior TEXT NULL, priority INT NOT NULL DEFAULT 0, FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_versions (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL, version INT NOT NULL, snapshot LONGTEXT NOT NULL, change_summary TEXT NOT NULL, created_by VARCHAR(191) NULL, created_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_skill_version(skill_id,version), FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_executions (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL, skill_version INT NOT NULL, workspace_id VARCHAR(36) NULL, project_id VARCHAR(36) NULL, agent_id VARCHAR(191) NULL, model_provider VARCHAR(191) NULL, model_name VARCHAR(191) NULL, task_summary TEXT NOT NULL, task_hash VARCHAR(191) NULL, started_at VARCHAR(40) NOT NULL, finished_at VARCHAR(40) NULL, duration_ms BIGINT NULL, status VARCHAR(32) NOT NULL, success BOOLEAN NOT NULL, tool_calls_count INT NULL, input_tokens INT NULL, output_tokens INT NULL, error_type VARCHAR(191) NULL, error_message TEXT NULL, feedback TEXT NULL, created_at VARCHAR(40) NOT NULL, KEY idx_executions_skill_model(skill_id,model_provider,model_name,success), FOREIGN KEY(skill_id) REFERENCES skills(id)) ENGINE=InnoDB;
